window.ME_DATA["y12-me"] = [
 {
  id:"l1", lesson:1, title:"الشيخ زايد: قيادة قائمة على القيم", unit:"الوحدة الأولى: نهج زايد الأخلاقي", art:"hero",
  dna:"فكّر في قائد (من أي مجال، في الماضي أو الحاضر) يثق به الناس. اكتب صفة واحدة تُكسبه هذه الثقة. ثم اسأل نفسك: هل يمكن أن يكون القائد فعّالًا من دون أن يكون أخلاقيًا؟ اكتب جملة واحدة تعبّر فيها عن رأيك.",
  dnaQs:["اذكر صفة واحدة تجعل القائد جديرًا بالثقة.","هل يمكن أن يكون القائد فعّالًا من دون أن يكون أخلاقيًا؟ عبّر عن رأيك في جملة واحدة."],
  dnaHint:"تذكر الإجابات القوية صفة محددة (النزاهة، التواضع، الثبات، حسن الإصغاء) بدلًا من صفة عامة مثل «جيد». أما في السؤال الثاني، فاتخذ موقفًا واضحًا: قد يحقق بعض القادة نتائج قصيرة المدى من دون أخلاق، لكن الثقة والشرعية والولاء طويل الأمد تعتمد في الغالب على القيم. ويُعدّ التمييز بين «الفاعلية على المدى القصير» و«الفاعلية على المدى البعيد» خطوة متقدمة في التفكير.",
  intentions:["أن أفهم المراحل الرئيسية في حياة المغفور له الشيخ زايد بن سلطان آل نهيان، طيّب الله ثراه، ومسيرته القيادية، من العين إلى تأسيس دولة الإمارات العربية المتحدة.","أن أحلّل كيف أسهمت قيم مثل التواضع والحكمة والصبر والقرب من الناس في تشكيل أسلوب الشيخ زايد في القيادة.","أن أقيّم الرأي القائل إن الشخصية الأخلاقية هي أساس القيادة الفعّالة والمستدامة."],
  criteria:["أستطيع أن أوجز المراحل الرئيسية في قيادة الشيخ زايد مع تواريخ دقيقة.","أستطيع أن أحلّل كيف أسهمت قيم محددة في تشكيل قراراته القيادية.","أستطيع أن أقيّم العلاقة بين الشخصية الأخلاقية والقيادة الفعّالة، مع مراعاة أكثر من وجهة نظر."],
  concept:{key:"الهوية", related:"القيادة، القيم، الشرعية", soi:"القيادة المتجذّرة في قيم أخلاقية ثابتة تبني الثقة والوحدة اللتين تمكّنان الأمة من النشوء والاستمرار.", context:"الهويات والعلاقات — استكشاف كيف تُسهم شخصية القائد في تشكيل هوية الأمة.", uae:"الشيخ زايد بن سلطان آل نهيان (نحو 1918–2004)، حاكم أبوظبي منذ عام 1966، وأول رئيس لدولة الإمارات العربية المتحدة من عام 1971 حتى عام 2004؛ وقد احتفت الدولة بمئوية ميلاده بإعلان عام 2018 «عام زايد». يرتبط الدرس بمادة التاريخ (تكوين الدولة) ومادة اللغة الإنجليزية (الكتابة التحليلية)."},
  words:[["القيادة القائمة على القيم (Values-based leadership)","أسلوب في القيادة تُوجَّه فيه القرارات بمبادئ أخلاقية ثابتة، لا بالسلطة أو بالمكاسب قصيرة المدى وحدها."],["الشرعية (Legitimacy)","القبول العام لدى الناس بأن سلطة القائد سلطة مستحقّة وجديرة بالاحترام."],["التواضع (Humility)","نظرة متواضعة إلى أهمية الذات، تظهر في الانفتاح على الآخرين والاستعداد للإصغاء إليهم."],["المجلس (Majlis)","مجلس أو لقاء تقليدي يلتقي فيه الناس بقائدهم مباشرة لعرض شؤونهم وطلب المشورة."],["الاتحاد (Federation)","اتحاد يضم إمارات أو ولايات تتمتع بقدر من الحكم الذاتي تحت حكومة مركزية واحدة، مثل الإمارات السبع في دولة الإمارات."],["الرؤية (Vision)","تصوّر واضح وبعيد المدى لما يطمح القائد إلى تحقيقه لشعبه."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار B — البحث والاستقصاء", steps:["أنشئ خطًا زمنيًا مشروحًا لمسيرة الشيخ زايد القيادية يتضمن خمس محطات رئيسية على الأقل (مثل دوره في العين منذ عام 1946، وتولّيه حكم أبوظبي عام 1966، وتأسيس دولة الإمارات في 2 ديسمبر 1971، ورئاسته للدولة حتى عام 2004).","استخدم مصدرين موثوقين على الأقل (مثل البوابات الحكومية الرسمية لدولة الإمارات، والأرشيف الوطني، والموسوعات الموثوقة).","دوّن لكل محطة قيمة واحدة جسّدتها أفعاله في ذلك الوقت، مع دليل موجز.","قيّم مصدرًا واحدًا: ما مدى موثوقيته؟ وهل هناك سبب قد يجعله يعرض وجهة نظر معيّنة؟"], prompts:["مصدراي","خمس محطات رئيسية مع تواريخها","القيمة التي تظهر في كل محطة، مع الدليل","تقييم موثوقية مصدر واحد ووجهة نظره"], success:"تتميّز الخطوط الزمنية القوية بالدقة (وُلد نحو عام 1918؛ ممثل الحاكم في العين منذ عام 1946؛ حاكم أبوظبي منذ عام 1966؛ أول رئيس لدولة الإمارات 1971–2004؛ تُوفي عام 2004)، وتربط كل حدث بقيمة محددة مدعومة بالدليل؛ فإقناع حكّام الإمارات بالاتحاد مثلًا يدل على الصبر والتشاور، واستثمار عائدات النفط في المدارس والإسكان والرعاية الصحية يدل على الاهتمام بالناس. وللوصول إلى أعلى مستوى، قيّم المصدر تقييمًا ناقدًا: فالمصادر الرسمية موثوقة في التواريخ والسياسات، لكنها تعرض المؤسس بصورة إيجابية بطبيعة الحال، لذا فإن التحقق منها بمرجع مستقل يعزّز البحث."},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"عندما بدأت عائدات النفط تُحدث تحولًا في أبوظبي في ستينيات القرن العشرين، كان بإمكان أي حاكم أن يستخدم الثروة الجديدة أساسًا لتعزيز سلطته الشخصية. لكن الشيخ زايد يُذكر على نطاق واسع بأنه وجّهها نحو المدارس والمستشفيات والإسكان والبنية التحتية، وبأنه واصل لقاء المواطنين العاديين في المجلس والإصغاء إلى همومهم بنفسه.", steps:["اكتب فقرة تحليلية (الفكرة، الدليل، الشرح، التقييم، الربط) تشرح فيها ما يكشفه هذا المقتطف عن القيادة القائمة على القيم.","استخدم أربع كلمات على الأقل من بنك الكلمات (مثل الشرعية، التواضع، المجلس، الرؤية) استخدامًا دقيقًا.","ضمّن فقرتك جملة تقييمية: لماذا قد تكون القيادة القائمة على القيم أكثر استدامة من القيادة القائمة على السلطة وحدها؟"], model:"يشير المقتطف إلى أن قيادة الشيخ زايد كانت قائمة على القيم لا على مراكمة السلطة الشخصية. فبتوجيهه ثروة النفط الجديدة نحو المدارس والمستشفيات والإسكان، أظهر رؤية بعيدة المدى تُسخَّر فيها موارد الوطن لخدمة شعبه، وبمواصلته لقاء المواطنين في المجلس أظهر تواضعًا وقربًا من الناس. وقد عزّزت هذه الخيارات شرعيته؛ إذ قَبِل الناس سلطته لا لأنه يتولّى المنصب فحسب، بل لأنهم رأوها تُستخدم لمصلحتهم. ويمكن القول إن القيادة القائمة على القيم أكثر استدامة من القيادة القائمة على السلطة وحدها، لأن الثقة المكتسبة بالسلوك الثابت تصمد في الأوقات الصعبة، في حين تميل السلطة القائمة على السيطرة وحدها إلى الضعف حين تُواجَه هذه السيطرة بالتحدي.", rubric:[["1–2","الكتابة وصفية لا تحليلية؛ استخدام قليل أو معدوم للمفردات الرئيسية."],["3–4","بعض التحليل لكنه غير مكتمل؛ استخدام مصطلح أو مصطلحين رئيسيين، وربما بصورة غير دقيقة."],["5–6","فقرة تحليلية واضحة؛ استخدام 3 مصطلحات رئيسية بدقة؛ محاولة للتقييم."],["7–8","تحليل متقدّم ومحكم البناء؛ استخدام 4 مصطلحات رئيسية أو أكثر بدقة؛ تقييم مقنع يبيّن لماذا تصنع القيم شرعية دائمة."]], starters:["يشير المقتطف إلى أن قيادة الشيخ زايد كانت قائمة على ___.","بتوجيهه الثروة نحو ___، أظهر ___.","عزّز ذلك شرعيته لأن ___.","يمكن القول إن القيادة القائمة على القيم أكثر استدامة لأن ___، في حين أن ___."]},
  task3:{title:"مهمة المشروع", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"ملف القيم القيادية", steps:["في مجموعات من 3–4 طلاب، حدّدوا أربع قيم أساسية ميّزت قيادة الشيخ زايد.","لكل قيمة، ابحثوا عن مثال موثّق جيدًا من حياته، واشرحوا كيف أثّر في قرار أو نتيجة.","قارنوا: اختاروا قيمة واحدة من هذه القيم وقدّروا كيف يمكن لقائد اليوم (في أي مجال — المدرسة أو الأعمال أو المجتمع) أن يطبّقها، وما العقبات التي قد تواجهه.","صمّموا «ملف القيم القيادية» في صفحة واحدة (إنفوجرافيك أو ملصق) يعرض نتائجكم.","قدّموا عرضًا مدته 4 دقائق، وأجيبوا عن سؤال تحدٍّ واحد من زملائكم. أعيدوا صياغة آرائه بدقة بدلًا من اختلاق أقوال منسوبة إليه."], rubric:[["1–2","القيم مُدرجة من دون أدلة؛ لا تطبيق على الحاضر."],["3–4","القيم مدعومة بأمثلة عامة؛ التطبيق غامض."],["5–6","القيم مدعومة بأمثلة دقيقة ومحددة؛ تطبيق واقعي مع تحديد عقبة."],["7–8","ملف عميق ومدعوم بالأدلة جيدًا؛ التطبيق على الحاضر ناقد ودقيق، ويوازن بين العقبات بصورة مقنعة."]]},
  game:{type:"sort", title:"قائمة على القيم أم على السلطة؟", prompt:"صنّف كل تصرّف قيادي: هل يعكس قيادة قائمة على القيم، أم قيادة قائمة أساسًا على السلطة والمصلحة الذاتية؟", bins:["قيادة قائمة على القيم","قائمة على السلطة / المصلحة الذاتية"], items:[["لقاء المواطنين العاديين بانتظام للاستماع إلى همومهم",0],["استثمار الثروة الوطنية في التعليم والرعاية الصحية للجميع",0],["إقناع الشركاء بصبر بالاتحاد بدلًا من إجبارهم عليه",0],["استخدام الأموال العامة أساسًا لإثراء دائرة صغيرة من الحلفاء",1],["رفض الإصغاء إلى المستشارين المخالفين في الرأي",1],["اتخاذ القرارات مع مراعاة مصلحة الجيل القادم",0],["إسكات الشكاوى بدلًا من معالجة أسبابها",1],["نسب جهود الآخرين إلى النفس لإظهار القوة",1]]},
  quiz:[["في أي عام تولّى الشيخ زايد حكم أبوظبي؟",["1946","1966","1971"],1],["تأسست دولة الإمارات العربية المتحدة في…",["2 ديسمبر 1971","6 أغسطس 1966","2 نوفمبر 2004"],0],["ماذا تعني «الشرعية» في سياق القيادة؟",["مقدار المال الذي يتحكم فيه القائد","حجم جيش القائد","القبول العام بأن سلطة القائد سلطة مستحقّة"],2],["ما الغرض من المجلس التقليدي؟",["مكان يلتقي فيه المواطنون بقائدهم مباشرة لعرض همومهم","ميدان للتدريب العسكري","سوق للتجارة"],0],["أيّ الخيارات الآتية يوضّح على أفضل وجه رؤية الشيخ زايد بعيدة المدى؟",["إبقاء عائدات النفط سرًّا","استثمار عائدات النفط في المدارس والمستشفيات والإسكان","حصر التعليم في عدد قليل من العائلات"],1],["لماذا أعلنت دولة الإمارات عام 2018 «عام زايد»؟",["لأنه العام الذي تأسست فيه الدولة","لأنه العام الذي اكتُشف فيه النفط","لأنه وافق مئوية ميلاده"],2],["أيّ الحجج الآتية تدعم على أفضل وجه الرأي القائل إن القيادة القائمة على القيم أكثر استدامة؟",["الثقة المكتسبة بالسلوك الثابت تصمد في الأوقات الصعبة","القادة أصحاب القيم لا يتعرّضون للنقد أبدًا","السلطة تدوم دائمًا أطول من الثقة"],0],["كم من الوقت تولّى الشيخ زايد رئاسة دولة الإمارات؟",["نحو 10 سنوات","من عام 1971 حتى وفاته عام 2004","خلال عام 1971 فقط"],1]],
  exit:"في جملة واحدة، حدّد القيمة التي ترى أنها كانت الأكثر محورية في قيادة الشيخ زايد، وعلّل اختيارك بالدليل.",
  copy:{facts:["تولّى الشيخ زايد بن سلطان آل نهيان (نحو 1918–2004) حكم أبوظبي عام 1966، وكان أول رئيس لدولة الإمارات من عام 1971 حتى وفاته عام 2004.","تُذكر قيادته بقيم مثل التواضع والصبر والتشاور والاهتمام بالناس، وقد تجلّى ذلك في استثمار ثروة النفط في التعليم والصحة والإسكان.","القيادة القائمة على القيم تبني الشرعية؛ إذ يقبل الناس السلطة التي يرونها تُستخدم لمصلحتهم. وقد احتفت دولة الإمارات بمئوية ميلاده بإعلان عام 2018 «عام زايد»."]},
  next:"في الدرس القادم: نواصل الوحدة الأولى بدراسة التسامح والتعايش في رؤية زايد."
 },
 {
  id:"l2", lesson:2, title:"التسامح والتعايش في رؤية زايد", unit:"الوحدة الأولى: نهج زايد الأخلاقي", art:"tolerance",
  dna:"مراجعة: اذكر قيمة واحدة أسهمت في تشكيل قيادة المغفور له الشيخ زايد بن سلطان آل نهيان، طيّب الله ثراه. والآن فكّر: تحتضن دولة الإمارات أشخاصًا من نحو 200 جنسية. هل «التسامح» كافٍ لكي يزدهر مجتمع متنوّع، أم أنه يحتاج إلى شيء أكثر؟ اكتب جملة واحدة تشرح فيها رأيك.",
  dnaQs:["اذكر قيمة واحدة أسهمت في تشكيل قيادة الشيخ زايد (من الدرس السابق).","هل «التسامح» كافٍ لكي يزدهر مجتمع متنوّع، أم أنه يحتاج إلى شيء أكثر؟"],
  dnaHint:"في المراجعة: التواضع أو الصبر أو التشاور أو الاهتمام بالناس كلها إجابات جيدة. أما في السؤال الثاني، فالإجابة القوية تميّز بين التسامح (تقبّل الاختلاف وعدم التمييز) والتعايش أو الأخوّة (العيش والعمل معًا بفاعلية في ظل الاحترام المتبادل). ويرى كثير من المفكرين أن التسامح هو الحدّ الأدنى، بينما يتطلب التعايش الحقيقي تفاعلًا إيجابيًا.",
  intentions:["أن أفهم كيف شكّل التسامح والتعايش جزءًا من نهج الشيخ زايد الأخلاقي ومن هوية دولة الإمارات.","أن أميّز بين التسامح والتقبّل والتعايش الفاعل.","أن أقيّم كيف تواصل مؤسسات دولة الإمارات ومبادراتها هذه الرؤية اليوم، وحدود التسامح."],
  criteria:["أستطيع أن أشرح دور التسامح والتعايش في رؤية زايد بأمثلة دقيقة.","أستطيع أن أميّز بوضوح بين التسامح والتقبّل والتعايش.","أستطيع أن أقيّم مدى تعبير المبادرات الحديثة عن هذه الرؤية، بما في ذلك مسألة ما إذا كان للتسامح حدود."],
  concept:{key:"التفاعلات العالمية", related:"التنوّع، الاحترام، التعايش", soi:"المجتمعات التي تتجاوز التسامح البسيط نحو التعايش الفاعل تهيّئ الظروف للازدهار المشترك والسلام.", context:"العولمة والاستدامة — استكشاف كيف تعيش المجتمعات المتنوّعة وتعمل معًا.", uae:"أنشأت دولة الإمارات وزارة للتسامح عام 2016، وأعلنت عام 2019 «عام التسامح»، ووُقّعت وثيقة الأخوّة الإنسانية في أبوظبي عام 2019. يرتبط الدرس بمادة التربية الإسلامية (احترام الآخرين) ونظرية المعرفة (النسبية الأخلاقية)."},
  words:[["التسامح (Tolerance)","الاستعداد لتقبّل المعتقدات أو الممارسات أو الأشخاص المختلفين عن الذات، من دون تمييز."],["التعايش (Coexistence)","العيش معًا بسلام في ظل الاحترام المتبادل، رغم الاختلاف في المعتقد أو الثقافة أو الخلفية."],["التعددية (Pluralism)","مجتمع يعيش فيه أشخاص من خلفيات ومعتقدات مختلفة كثيرة معًا، ويشاركون فيه على قدم المساواة."],["التمييز (Discrimination)","المعاملة الظالمة للناس بسبب خصائص مثل الدين أو العرق أو الجنسية."],["الأخوّة (Fraternity)","شعور بالأخوّة والإنسانية المشتركة بين أشخاص من خلفيات مختلفة."],["التماسك الاجتماعي (Social cohesion)","روابط الثقة والتضامن التي تحافظ على تماسك المجتمع المتنوّع."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار B — البحث والاستقصاء", steps:["اختر مبادرة إماراتية واحدة تعكس التسامح والتعايش (مثل وزارة التسامح التي أُنشئت عام 2016، أو عام التسامح 2019، أو وثيقة الأخوّة الإنسانية الموقّعة في أبوظبي عام 2019، أو بيت العائلة الإبراهيمية).","ابحث عنها مستخدمًا مصدرين موثوقين على الأقل.","دوّن: ما هي، ومتى بدأت، وما الذي تهدف إلى تحقيقه.","اشرح كيف ترتبط بالقيم التي رسّخها الشيخ زايد.","حدّد تحديًا واحدًا أو نقدًا واحدًا قد تواجهه مثل هذه المبادرات، وكيف يمكن معالجته."], prompts:["المبادرة التي اخترتها ومصدراي","ما هي، ومتى بدأت، وما الذي تهدف إلى تحقيقه","كيف ترتبط بقيم زايد","تحدٍّ أو نقد واحد، وكيف يمكن معالجته"], success:"تقدّم الإجابات القوية تفاصيل دقيقة (فمثلًا، وُقّعت وثيقة الأخوّة الإنسانية في أبوظبي في فبراير 2019 من قِبل البابا فرنسيس وشيخ الأزهر)، وتربط ربطًا صريحًا برؤية زايد لمجتمع يعيش فيه أشخاص من جنسيات وأديان مختلفة في ظل الاحترام المتبادل. وللوصول إلى أعلى مستوى، تعامل مع الموضوع تعاملًا ناقدًا: فمن التحديات الشائعة الفجوة بين المبادرات الرمزية والتجربة اليومية، لذا فإن أكثر الإجابات إقناعًا هي التي تقترح كيف يمكن أن تُلمَس السياسة في الحياة اليومية — في أماكن العمل والمدارس والأحياء."},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"رأى أحد الفلاسفة أن المجتمع المتسامح يواجه مفارقة: فإذا تسامح مع كل شيء، بما في ذلك من يدعون إلى الكراهية وعدم التسامح، فقد ينتهي به الأمر إلى أن يُدمَّر على أيديهم. لذلك يرى بعضهم أن التسامح يجب أن تكون له حدود.", steps:["اكتب فقرة جدلية تجيب فيها عن السؤال: «هل يجب أن تكون للتسامح حدود؟»","استخدم أربع كلمات على الأقل من بنك الكلمات (مثل التسامح، التعايش، التمييز، التماسك الاجتماعي) استخدامًا دقيقًا.","أشر إلى سياق دولة الإمارات (مثل تشريعاتها لمكافحة التمييز أو رؤيتها للتعايش)، وتوصّل إلى استنتاج مُعلَّل."], model:"التسامح ضروري للمجتمع التعددي، لكنه لا يمكن أن يكون مطلقًا من دون أن يقوّض نفسه. فلو تسامح المجتمع مع خطاب الكراهية والتمييز، لفقد الأشخاص الأكثر اعتمادًا على التسامح — الأقليات والوافدون الجدد — أمنهم، ولانهار التماسك الاجتماعي. ولهذا السبب تحمي دول كثيرة، ومنها دولة الإمارات من خلال تشريعاتها لمكافحة التمييز، حرية المعتقد مع حظر التحريض على الكراهية. ويعكس ذلك منطق رؤية زايد: فالتعايش لم يكن لامبالاة تجاه كل سلوك، بل احترامًا متبادلًا بين الناس. لذلك أستنتج أن التسامح يجب أن تكون له حدود، على أن تكون هذه الحدود ضيّقة وقائمة على المبادئ، تستهدف الإضرار بالآخرين لا مجرد الاختلاف في الرأي.", rubric:[["1–2","حجة ضعيفة؛ استخدام محدود أو معدوم للمفردات الرئيسية."],["3–4","موقف أساسي بتعليل محدود؛ استخدام مصطلح أو مصطلحين رئيسيين."],["5–6","حجة واضحة ومُعلَّلة؛ استخدام 3 مصطلحات رئيسية بدقة؛ بعض الإشارة إلى سياق دولة الإمارات."],["7–8","حجة متقدّمة ومتوازنة؛ استخدام 4 مصطلحات رئيسية أو أكثر بدقة؛ دمج سياق دولة الإمارات؛ استنتاج دقيق وقائم على المبادئ."]], starters:["التسامح ضروري للمجتمع التعددي، لكن ___.","لو تسامح المجتمع مع ___، فإن ___.","يعكس ذلك رؤية زايد لأن ___.","لذلك أستنتج أن التسامح يجب / لا يجب أن تكون له حدود، لأن ___."]},
  task3:{title:"مهمة المشروع", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"تدقيق التعايش", steps:["في مجموعات من 3–4 طلاب، صمّموا استبانة قصيرة مجهولة الهوية (5–6 أسئلة) لاستكشاف كيف يعيش طلاب صفكم تجربة التعايش في الحياة المدرسية.","تأكّدوا من أن الأسئلة محترمة ومحايدة ولا تكشف هوية الأفراد.","اجمعوا إجابات 15 زميلًا على الأقل (بموافقة المعلم)، ولخّصوا النتائج.","حدّدوا نقطة قوة واحدة ومجالًا واحدًا للتطوير في ثقافة التعايش في مدرستكم.","اقترحوا مبادرة عملية مستوحاة من قيم زايد، وقدّموها في عرض مدته 4 دقائق، مستخدمين مفردات بنك الكلمات."], rubric:[["1–2","استبانة سيئة التصميم أو منحازة؛ النتائج غير محلّلة."],["3–4","استبانة أساسية؛ النتائج موصوفة لكنها غير مفسّرة."],["5–6","استبانة جيدة التصميم؛ النتائج محلّلة؛ مبادرة واقعية مقترحة."],["7–8","استبانة أخلاقية وجيدة التصميم؛ تحليل عميق للنتائج؛ المبادرة عملية وقائمة على الأدلة ومرتبطة بوضوح برؤية زايد."]]},
  game:{type:"sort", title:"تسامح أم تعايش أم لا هذا ولا ذاك؟", prompt:"صنّف كل مثال: هل يُظهر تسامحًا أساسيًا (تقبّل الاختلاف)، أم تعايشًا فاعلًا (التفاعل معًا)، أم لا هذا ولا ذاك؟", bins:["تسامح أساسي","تعايش فاعل","لا هذا ولا ذاك (تمييز)"], items:[["عدم الاعتراض عندما يحتفل جارك بعيد ديني مختلف",0],["دعوة زملاء من أديان مختلفة لمشاركة الإفطار",1],["رفض توظيف شخص بسبب جنسيته",2],["تقبّل أن يحمل زملاء الصف آراء مختلفة من دون السخرية منهم",0],["تنظيم مشروع مجتمعي مشترك مع أشخاص من ثقافات متعددة",1],["نشر نكات تكرّس صورًا نمطية عن مجموعة عرقية معيّنة",2],["التعرّف إلى ثقافة زميل في الصف ومشاركته ثقافتك",1],["استبعاد شخص من مجموعة بسبب لهجته",2]]},
  quiz:[["في أي عام أنشأت دولة الإمارات وزارة للتسامح؟",["2016","2004","2019"],0],["في أي عام أعلنت دولة الإمارات «عام التسامح»؟",["2018","2021","2019"],2],["ما الفرق بين التسامح والتعايش؟",["لهما المعنى نفسه تمامًا","التسامح يتقبّل الاختلاف؛ والتعايش يعني العيش معًا بفاعلية في ظل الاحترام المتبادل","التعايش يعني أن يفكر الجميع بالطريقة نفسها"],1],["ماذا تصف «التعددية»؟",["مجتمعًا يشارك فيه أشخاص من خلفيات متعددة على قدم المساواة","مجتمعًا له ثقافة رسمية واحدة فقط","نوعًا من الأنظمة الاقتصادية"],0],["وُقّعت وثيقة الأخوّة الإنسانية (2019) في…",["القاهرة","روما","أبوظبي"],2],["ما «مفارقة التسامح»؟",["التسامح يُضعف المجتمعات دائمًا","التسامح المطلق مع عدم التسامح قد يتيح لعدم التسامح تدمير المجتمع المتسامح","يستحيل تعريف التسامح"],1],["أيّ الحدود الآتية هو الحدّ الأكثر استنادًا إلى المبادئ للتسامح؟",["منع كل من يحمل آراء مختلفة","حظر التحريض على الكراهية مع حماية حرية المعتقد","التسامح مع أبناء بلدك فقط"],1],["كيف ترتبط رؤية زايد بتنوّع دولة الإمارات اليوم؟",["شجّعت الاحترام المتبادل بين أشخاص من جنسيات وأديان كثيرة","هدفت إلى إبقاء المجتمعات منفصلة تمامًا","لم تكن لها صلة بالتنوّع"],0]],
  exit:"في جملة واحدة، اشرح الفرق بين أن تتسامح مع شخص ما وأن تتعايش معه.",
  copy:{facts:["التسامح يعني تقبّل الاختلاف من دون تمييز؛ أما التعايش فيذهب أبعد من ذلك، ويعني أن يعيش الناس ويعملوا معًا بفاعلية في ظل الاحترام المتبادل.","تتواصل رؤية زايد للتعايش في المبادرات الإماراتية: وزارة التسامح (2016)، وعام التسامح (2019)، ووثيقة الأخوّة الإنسانية الموقّعة في أبوظبي (2019).","يمكن القول إن التسامح يحتاج إلى حدود قائمة على المبادئ: فحماية حرية المعتقد مع حظر التحريض على الكراهية تحافظ على تماسك المجتمع المتنوّع."]},
  next:"في الدرس القادم: نواصل الوحدة الأولى باستكشاف الكرم والعطاء والعمل الإنساني في نهج زايد."
 },
 {
  id:"l3", lesson:3, title:"الكرم والعطاء والعمل الإنساني", unit:"الوحدة الأولى: نهج زايد الأخلاقي", art:"globe",
  dna:"مراجعة: في جملة واحدة، اشرح الفرق بين التسامح والتعايش. والآن فكّر: إذا قدّمت دولة غنية مساعدات إلى دولة أخرى، فهل هذا كرم، أم أنه يخدم مصلحتها الخاصة؟ وهل يمكن أن يكون الأمرين معًا؟ اكتب جملة واحدة.",
  dnaQs:["ما الفرق بين التسامح والتعايش (من الدرس السابق)؟","هل مساعدات الدولة الغنية كرم، أم مصلحة ذاتية، أم الأمران معًا؟"],
  dnaHint:"في المراجعة: التسامح يتقبّل الاختلاف، بينما يعني التعايش العيش معًا بفاعلية في ظل الاحترام المتبادل. أما في السؤال الثاني، فالإجابة الدقيقة تدرك أن الدوافع قد تكون مختلطة: فالمساعدات قد تخفّف المعاناة وتبني في الوقت نفسه الصداقات والاستقرار. وتشير تقاليد أخلاقية كثيرة، ومنها التعاليم الإسلامية حول إخلاص النيّة، إلى أن نقاء الدافع مهم، لكن نفع المحتاجين مهم أيضًا.",
  intentions:["أن أفهم مكانة الكرم والعطاء الإنساني في النهج الأخلاقي للمغفور له الشيخ زايد بن سلطان آل نهيان، طيّب الله ثراه، وفي القيم الإسلامية.","أن أحلّل كيف يتواصل هذا الإرث من خلال المؤسسات الإنسانية الإماراتية ويوم زايد للعمل الإنساني.","أن أقيّم ما الذي يجعل العطاء أخلاقيًا وفعّالًا ومحترمًا لكرامة متلقّيه."],
  criteria:["أستطيع أن أشرح دور الكرم في نهج زايد وجذوره في القيم الإسلامية.","أستطيع أن أحلّل مؤسسة أو مبادرة إنسانية إماراتية واحدة على الأقل تحليلًا دقيقًا.","أستطيع أن أقيّم ما الذي يجعل العطاء الإنساني أخلاقيًا وفعّالًا، مع مراعاة وجهات نظر مختلفة."],
  concept:{key:"التفاعلات العالمية", related:"المسؤولية، الرحمة، الكرامة", soi:"الكرم الذي يحترم كرامة المتلقّين ويلبّي احتياجات حقيقية يعكس مسؤولية أخلاقية تتجاوز الحدود الوطنية.", context:"العدالة والتنمية — استكشاف المسؤولية تجاه المحتاجين محليًا وعالميًا.", uae:"يُحيا يوم زايد للعمل الإنساني في 19 رمضان، ذكرى وفاته؛ ويتواصل العمل الإنساني لدولة الإمارات من خلال مؤسسات مثل هيئة الهلال الأحمر الإماراتي وصندوق أبوظبي للتنمية. يرتبط الدرس بمادة التربية الإسلامية (الزكاة والصدقة) ومادة الاقتصاد (المساعدات التنموية)."},
  words:[["العمل الإنساني (Humanitarianism)","الاهتمام الفاعل برفاه الإنسان، ولا سيما من خلال تخفيف المعاناة في الأزمات."],["العمل الخيري (Philanthropy)","الرغبة في تعزيز رفاه الآخرين، غالبًا من خلال التبرّع السخي بالمال أو الموارد."],["الزكاة (Zakat)","العطاء السنوي الواجب لجزء من المال في الإسلام، وهي أحد أركان الإسلام الخمسة."],["الصدقة (Sadaqah)","العطاء الخيري التطوّعي في الإسلام، يُقدَّم رحمةً وبنيّة صادقة."],["التنمية المستدامة (Sustainable development)","تنمية تلبّي احتياجات الحاضر من دون المساس بقدرة الأجيال القادمة على تلبية احتياجاتها."],["كرامة المتلقّي (Dignity of the recipient)","مبدأ يقضي بتقديم المساعدة بطريقة تحترم قيمة متلقّيها وقدرتهم على الاختيار وخصوصيتهم."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار B — البحث والاستقصاء", steps:["اختر مؤسسة أو مشروعًا إنسانيًا إماراتيًا واحدًا (مثل هيئة الهلال الأحمر الإماراتي، أو صندوق أبوظبي للتنمية، أو مؤسسة زايد بن سلطان آل نهيان للأعمال الخيرية والإنسانية، أو جهد إغاثي إماراتي موثّق جيدًا).","ابحث عنه مستخدمًا مصدرين موثوقين على الأقل.","دوّن: غايته، ونوع المساعدة التي يقدّمها، ومثالًا محددًا واحدًا على عمله.","صنّف المثال: هل هو إغاثة طارئة أم تنمية طويلة الأمد؟ اشرح الفرق بينهما.","اربطه بإرث زايد وبيوم زايد للعمل الإنساني (19 رمضان)."], prompts:["المؤسسة أو المشروع الذي اخترته ومصدراي","غايته ونوع المساعدة التي يقدّمها","مثال محدد واحد على عمله","إغاثة طارئة أم تنمية طويلة الأمد؟ ولماذا؟","كيف يرتبط بإرث زايد"], success:"تقدّم الإجابات القوية مثالًا محددًا يمكن التحقق منه (دولة أو نوع مشروع أو سنة) بدلًا من وصف عام. ويجب شرح الفرق بين الإغاثة الطارئة (الغذاء والمأوى والرعاية الطبية في الأزمات) والتنمية طويلة الأمد (المدارس والمستشفيات وشبكات المياه والبنية التحتية) بوضوح. وللوصول إلى أعلى مستوى، قيّم سبب أهمية كليهما: فالإغاثة الطارئة تنقذ الأرواح فورًا، بينما تقلّل التنمية من الهشاشة مستقبلًا — وهذا يعكس رؤية زايد بأن العطاء ينبغي أن يحسّن حياة الناس تحسينًا دائمًا."},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"بعد كارثة طبيعية، تنشر جمعية خيرية على الإنترنت صورًا لمتلقّي المساعدات وهم يتسلّمون طرودًا غذائية، وتظهر وجوههم بوضوح. تجمع هذه المنشورات مبالغ كبيرة لمزيد من المساعدات، لكن بعض المنتقدين يرون أنها تمسّ كرامة الأشخاص الظاهرين في الصور.", steps:["اكتب فقرة تقييمية تتناول السؤال: «هل يبرّر الخير الذي تحققه الجمعية الخيرية الطريقة التي تروّج بها لعملها؟»","استخدم أربع كلمات على الأقل من بنك الكلمات (مثل العمل الإنساني، كرامة المتلقّي، الصدقة، العمل الخيري) استخدامًا دقيقًا.","استند إلى المبدأ الإسلامي القائل إن أفضل الصدقة كثيرًا ما تكون سرًّا، وتوصّل إلى استنتاج متوازن ومُعلَّل."], model:"يحقق ترويج الجمعية لعملها خيرًا إنسانيًا واضحًا، إذ تتيح الأموال المجموعة وصول مزيد من المساعدات إلى المتضرّرين من الأزمة. غير أن مبدأ كرامة المتلقّي يشير إلى أن المحتاجين لا ينبغي أن يصبحوا مشهدًا مقابل الدعم. فالتعاليم الإسلامية حول الصدقة تُعلي من شأن العطاء في السر، وتحذّر من أن تكون الصدقة سببًا في إذلال من يتلقّاها، وهذا يعكس اهتمامًا أخلاقيًا أوسع بأن يحترم العمل الخيري خصوصية الناس وقدرتهم على الاختيار. ويمكن لنهج متوازن أن يسمح للجمعية بالترويج لعملها مع حماية المتلقّين، مثلًا بالحصول على موافقتهم، أو تجنّب إظهار الوجوه، أو رواية القصص بأصوات من تلقّوا المساعدة. لذلك أستنتج أن الخير المتحقق لا يبرّر الطريقة تبريرًا كاملًا، لأن العطاء الفعّال والعطاء المحترم لا يتعارضان بالضرورة.", rubric:[["1–2","تقييم ضعيف؛ استخدام محدود أو معدوم للمفردات الرئيسية."],["3–4","حكم أساسي بتعليل محدود؛ استخدام مصطلح أو مصطلحين رئيسيين."],["5–6","تقييم واضح يوازن بين الجانبين؛ استخدام 3 مصطلحات رئيسية بدقة؛ إشارة إلى المبادئ الإسلامية."],["7–8","تقييم متقدّم ومتوازن؛ استخدام 4 مصطلحات رئيسية أو أكثر بدقة؛ تطبيق المبادئ بعمق؛ الاستنتاج يقدّم حلًا عمليًا."]], starters:["يحقق ترويج الجمعية لعملها ___ بوضوح، إذ ___.","غير أن مبدأ كرامة المتلقّي يشير إلى ___.","تُعلي التعاليم الإسلامية حول الصدقة من شأن ___، وهذا ___.","يمكن لنهج متوازن أن ___، لذلك أستنتج أن ___."]},
  task3:{title:"مهمة المشروع", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"حملة العطاء الأخلاقي", steps:["في مجموعات من 3–4 طلاب، صمّموا حملة مدرسية بمناسبة يوم زايد للعمل الإنساني (19 رمضان) تدعم جمعية خيرية إماراتية حقيقية وذات سمعة طيبة.","قرّروا ما إذا كانت حملتكم تدعم الإغاثة الطارئة أم التنمية طويلة الأمد، وعلّلوا اختياركم.","اكتبوا «ميثاق العطاء الأخلاقي» قصيرًا (4–5 مبادئ) تلتزم به حملتكم، مثل حماية كرامة المتلقّين، والشفافية في بيان أوجه صرف الأموال.","صمّموا مواد الحملة (ملصق، أو نص قصير، أو خطة لوسائل التواصل الاجتماعي) بما يتوافق مع ميثاقكم.","قدّموا عرضًا مدته 4 دقائق، تشرحون فيه كيف تعكس حملتكم إرث زايد في العطاء."], rubric:[["1–2","الحملة غامضة؛ لم تُحدَّد مبادئ أخلاقية."],["3–4","حملة أساسية بمبادئ عامة؛ تعليل محدود."],["5–6","حملة واضحة ذات تركيز مُعلَّل؛ الميثاق الأخلاقي ذو صلة ومطبّق في المواد."],["7–8","حملة واقعية ومُعلَّلة جيدًا؛ الميثاق الأخلاقي عميق ومطبّق باتساق؛ ربط قوي ومحدد بإرث زايد."]]},
  game:{type:"sort", title:"إغاثة أم تنمية؟", prompt:"صنّف كل عمل إنساني: هل هو إغاثة طارئة (للبقاء على قيد الحياة فورًا) أم تنمية طويلة الأمد (لتحسين دائم)؟", bins:["إغاثة طارئة","تنمية طويلة الأمد"], items:[["إرسال طرود غذائية وخيام بعد زلزال",0],["بناء مدرسة في مجتمع ريفي",1],["إرسال فرق طبية جوًّا لعلاج المصابين بعد فيضان",0],["تمويل نظام لتنقية المياه لبلدة",1],["توفير مآوٍ مؤقتة للأسر النازحة",0],["تدريب ممرضين وأطباء محليين",1],["توزيع البطانيات خلال موجة برد مفاجئة",0],["إعادة بناء البنية التحتية مثل السدود والطرق",1]]},
  quiz:[["متى يُحيا يوم زايد للعمل الإنساني؟",["19 رمضان","2 ديسمبر","1 محرّم"],0],["لماذا اختير يوم 19 رمضان؟",["لأنه ذكرى تأسيس دولة الإمارات","لأنه ذكرى وفاة الشيخ زايد","لأنه أول أيام العيد"],1],["ما الفرق بين الزكاة والصدقة؟",["لا يوجد فرق","الصدقة واجبة؛ والزكاة تطوّعية","الزكاة عطاء سنوي واجب؛ والصدقة عطاء خيري تطوّعي"],2],["ماذا تعني «كرامة المتلقّي»؟",["أن تُقدَّم المساعدة بطريقة تحترم قيمة متلقّيها وخصوصيتهم","أن على المتلقّين شكر المتبرّعين علنًا","أن الأغنياء وحدهم يستحقون المساعدة"],0],["بناء مستشفى في منطقة نامية مثال على…",["الإغاثة الطارئة","التنمية طويلة الأمد","لا هذا ولا ذاك"],1],["أيّ مما يأتي حجة قوية لصالح المساعدات التنموية طويلة الأمد؟",["أنها دائمًا أقل كلفة من المساعدات الطارئة","أنها تعني أن الطوارئ لن تحدث أبدًا","أنها تقلّل من الهشاشة والاعتماد على الغير مستقبلًا"],2],["هل يمكن أن تكون مساعدات دولة ما كرمًا وتخدم مصلحتها في الوقت نفسه؟",["نعم — قد تكون الدوافع مختلطة، لكن نفع المحتاجين يظل مهمًا","لا — أي مصلحة ذاتية تلغي الكرم","لا — المساعدات أنانية بحتة دائمًا"],0],["أيّ المؤسسات الإماراتية الآتية ترتبط أساسًا بالإغاثة الإنسانية؟",["هيئة الهلال الأحمر الإماراتي","المجلس الوطني الاتحادي","وزارة التسامح"],0]],
  exit:"في جملة واحدة، اشرح مبدأً واحدًا يجعل العطاء أخلاقيًا، لا سخيًّا فحسب.",
  copy:{facts:["كان الكرم محوريًا في نهج الشيخ زايد الأخلاقي، وهو متجذّر في القيم الإسلامية للزكاة (العطاء الواجب) والصدقة (العطاء التطوّعي).","يواصل يوم زايد للعمل الإنساني، الذي يُحيا في 19 رمضان ذكرى وفاته، إرثه من خلال مؤسسات إماراتية مثل هيئة الهلال الأحمر الإماراتي.","يوازن العطاء الأخلاقي بين الإغاثة الطارئة والتنمية طويلة الأمد، ويحمي دائمًا كرامة المتلقّي."]},
  next:"في الدرس القادم: نواصل الوحدة الأولى باستكشاف العدل والشورى والوحدة في نهج زايد."
 },
 {
  id:"l4", lesson:4, title:"العدل والشورى والوحدة", unit:"الوحدة الأولى: نهج زايد الأخلاقي", art:"fair",
  dna:"مراجعة: اذكر مبدأً واحدًا من مبادئ العطاء الأخلاقي من الدرس السابق. والآن فكّر: في عام 1971، اتفق حكّام عدة إمارات منفصلة على تكوين اتحاد واحد. لماذا قد يصعب على حكّام مستقلّين الاتفاق على الاتحاد؟ اكتب عقبتين محتملتين.",
  dnaQs:["اذكر مبدأً واحدًا من مبادئ العطاء الأخلاقي (من الدرس السابق).","لماذا قد يصعب على حكّام مستقلّين الاتفاق على الاتحاد؟ اذكر عقبتين."],
  dnaHint:"في المراجعة: احترام كرامة المتلقّي، أو الشفافية، أو الموازنة بين الإغاثة والتنمية طويلة الأمد. ومن العقبات أمام الاتحاد: الخوف من فقدان الاستقلال، والتفاوت في الثروة وعدد السكان بين الإمارات، والخلافات حول كيفية تقاسم السلطة، والتنافسات التاريخية. وتدرك الإجابات الجيدة أن الوحدة تطلّبت الثقة والتنازلات العادلة.",
  intentions:["أن أفهم مبدأي العدل والشورى وجذورهما في التقاليد الإسلامية والإماراتية.","أن أحلّل كيف أسهم التشاور والإنصاف في مساعدة المغفور له الشيخ زايد بن سلطان آل نهيان، طيّب الله ثراه، على بناء الوحدة بين الإمارات.","أن أقيّم نقاط القوة والتحديات في صنع القرار القائم على التشاور في الدولة الحديثة وفي الحياة اليومية."],
  criteria:["أستطيع أن أشرح مبدأي العدل والشورى مع إشارات دقيقة إلى التقاليد.","أستطيع أن أحلّل كيف أسهم التشاور والإنصاف في تأسيس دولة الإمارات ووحدتها.","أستطيع أن أقيّم نقاط القوة والقيود في صنع القرار القائم على التشاور في سياقات مختلفة."],
  concept:{key:"الأنظمة", related:"العدل، الشورى، الوحدة", soi:"صنع القرار القائم على العدل والتشاور يبني الثقة اللازمة لتوحيد مجموعات متنوّعة في كيان مستقر.", context:"العدالة والتنمية — استكشاف كيف تصنع الإجراءات العادلة وحدة دائمة.", uae:"ورد مبدأ الشورى في القرآن الكريم (سورة الشورى)؛ وتأسس الاتحاد الإماراتي في 2 ديسمبر 1971، وأُنشئ المجلس الوطني الاتحادي عام 1972 هيئةً استشارية. يرتبط الدرس بمادتي السياسة العالمية والتاريخ."},
  words:[["الشورى (Shura)","المبدأ الإسلامي في التشاور، إذ تُتخذ القرارات بعد استطلاع آراء الآخرين."],["العدل (Justice)","المعاملة المنصفة لجميع الناس، وإعطاء كل ذي حق حقه."],["الإجماع / التوافق (Consensus)","اتفاق عام تتوصّل إليه مجموعة بعد النقاش، بدلًا من فرض رأي واحد."],["الوحدة (Unity)","حالة الاتحاد في كيان واحد، مع احترام هويات أجزائه."],["التسوية / التنازل المتبادل (Compromise)","اتفاق يتنازل فيه كل طرف عن شيء ما للوصول إلى تسوية عادلة."],["الإنصاف (Equity)","عدالة تراعي اختلاف الاحتياجات والظروف، بدلًا من معاملة الجميع بالطريقة نفسها تمامًا."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار A — المعرفة والفهم", steps:["ابحث في تأسيس الاتحاد الإماراتي عام 1971 ودور التشاور فيه، مستخدمًا مصدرين موثوقين على الأقل.","دوّن: الإمارات التي كوّنت الاتحاد في 2 ديسمبر 1971، والإمارة التي انضمت بعد ذلك بوقت قصير عام 1972.","حدّد مثالًا واحدًا على التنازل المتبادل أو التشاور أسهم في جعل الاتحاد ممكنًا (مثل المفاوضات بين الحكّام، أو الاتفاقات حول كيفية حكم الاتحاد).","ابحث في دور المجلس الوطني الاتحادي (أُنشئ عام 1972)، واشرح كيف يعكس مبدأ الشورى."], prompts:["مصدراي","الإمارات التي كوّنت الاتحاد عام 1971، والإمارة التي انضمت عام 1972","مثال واحد على التنازل المتبادل أو التشاور","كيف يعكس المجلس الوطني الاتحادي مبدأ الشورى"], success:"تذكر الإجابات الدقيقة أن ست إمارات كوّنت الاتحاد في 2 ديسمبر 1971 (أبوظبي، ودبي، والشارقة، وعجمان، وأم القيوين، والفجيرة)، وأن رأس الخيمة انضمت في مطلع عام 1972. وتشرح الإجابات القوية أن الاتحاد تطلّب من الحكّام التفاوض حول كيفية تقاسم السلطة والموارد، وأن الشيخ زايد يُذكر بالإقناع الصبور لا بالقوة. وللوصول إلى أعلى مستوى، اشرح دور المجلس الوطني الاتحادي بوصفه هيئة استشارية تناقش التشريعات وتطرح هموم المواطنين، واربطه ربطًا صريحًا بتقليد المجلس ومبدأ الشورى."},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"يجب على مجلس طلابي أن يقرّر كيفية إنفاق ميزانية محدودة. يقترح أحد الأعضاء أن يتخذ رئيس المجلس القرار بنفسه، لأن استشارة الجميع ستستغرق وقتًا طويلًا. ويرى عضو آخر أنه يجب استشارة طلاب كل صف دراسي أولًا، حتى لو تأخّر القرار.", steps:["اكتب فقرة تقييمية حول السؤال: «هل يستحق التشاور دائمًا الوقت الذي يستغرقه؟»","استخدم أربع كلمات على الأقل من بنك الكلمات (مثل الشورى، التوافق، العدل، الإنصاف) استخدامًا دقيقًا.","استند إلى مثال تأسيس دولة الإمارات، وتوصّل إلى استنتاج مُعلَّل يقرّ بالحالات التي قد تستدعي اتخاذ قرارات سريعة."], model:"كثيرًا ما يستحق التشاور الوقت الذي يستغرقه، لأن القرارات المتخذة بالشورى تحظى بشرعية أكبر ويكون قبولها أرجح. ويوضّح تأسيس دولة الإمارات ذلك: فبدلًا من فرض الاتحاد، تفاوض الحكّام وتنازلوا تنازلات متبادلة حتى تحقّق التوافق، وقد أسهمت تلك العملية الصبورة في إنشاء اتحاد صمد لأكثر من خمسة عقود. وفي المجلس الطلابي، من شأن استشارة طلاب كل صف دراسي أن تعزّز الإنصاف، بضمان مراعاة احتياجات الطلاب الأصغر سنًّا والأكبر سنًّا معًا، بدلًا من الاكتفاء برأي الرئيس. غير أن التشاور لا يكون مناسبًا دائمًا: ففي حالات الطوارئ قد يسبّب التأخير ضررًا، لذا قد يحتاج القائد إلى التصرّف بسرعة وشرح القرار لاحقًا. لذلك أستنتج أن التشاور ينبغي أن يكون الأصل في القرارات التي تمسّ المجتمع بأكمله، بينما ينبغي أن تقتصر القرارات السريعة على حالات الاستعجال الحقيقية، وأن تظل خاضعة للمساءلة أمام المتأثرين بها.", rubric:[["1–2","تقييم ضعيف؛ استخدام محدود أو معدوم للمفردات الرئيسية."],["3–4","موقف أساسي بتعليل محدود؛ استخدام مصطلح أو مصطلحين رئيسيين."],["5–6","تقييم واضح مع إشارة إلى مثال دولة الإمارات؛ استخدام 3 مصطلحات رئيسية بدقة."],["7–8","تقييم متقدّم ومتوازن؛ استخدام 4 مصطلحات رئيسية أو أكثر بدقة؛ دمج مثال دولة الإمارات؛ الاستنتاج يميّز بوضوح بين السياقات."]], starters:["كثيرًا ما يستحق التشاور الوقت الذي يستغرقه لأن ___.","يوضّح تأسيس دولة الإمارات ذلك، إذ ___.","في المجلس الطلابي، من شأن استشارة طلاب كل صف دراسي أن ___.","غير أن التشاور قد لا يكون مناسبًا عندما ___، لذلك أستنتج أن ___."]},
  task3:{title:"مهمة المشروع", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"محاكاة الشورى", steps:["في مجموعات من 5–6 طلاب، يؤدي كل عضو دور ممثّل لمجتمع افتراضي له احتياجات وموارد وأولويات مختلفة.","يجب أن تتفق مجموعاتكم على خطة مشتركة لمورد محدود (مثل ميزانية لمرفق مجتمعي جديد) من خلال التشاور.","سجّلوا مجريات العملية: ما أراده كل ممثّل، والتنازلات التي قُدّمت، وكيف تحقّق التوافق (أو لم يتحقّق).","قارنوا عمليتكم بمبادئ الشورى وبتأسيس دولة الإمارات.","قدّموا تأمّلًا مدته 4 دقائق: ما الذي أدّى إلى نجاح التشاور أو تعثّره، وماذا تعلّمتم عن العدل والوحدة؟"], rubric:[["1–2","تشاور حقيقي محدود؛ تأمّل سطحي."],["3–4","بعض التشاور؛ التأمّل يصف العملية من دون تحليل."],["5–6","تشاور حقيقي مع تسجيل التنازلات؛ مقارنة واضحة بالشورى وبتأسيس دولة الإمارات."],["7–8","تشاور ماهر وتنازلات قائمة على المبادئ؛ تأمّل عميق وناقد يربط التجربة بالعدل والإنصاف والوحدة."]]},
  game:{type:"sort", title:"شورى أم لا؟", prompt:"صنّف كل طريقة لاتخاذ القرار: هل تعكس مبدأ الشورى (التشاور)، أم لا؟", bins:["تعكس الشورى","لا تعكس الشورى"], items:[["قائد يطلب المشورة من مستشارين ذوي خبرة قبل اتخاذ القرار",0],["مجلس يناقش مقترحًا ويتوصّل إلى توافق",0],["حاكم يتخذ قرارًا مهمًا من دون الاستماع إلى أيٍّ من المتأثرين به",1],["مواطنون يطرحون همومهم من خلال هيئة تمثيلية",0],["قائد مجموعة يتجاهل أفكار الأعضاء ويقرّر وحده",1],["ممثّلون يتفاوضون ويتنازلون تنازلات متبادلة للوصول إلى اتفاق",0],["إسكات رأي الأقلية توفيرًا للوقت",1],["عقد مجلس يستطيع فيه الناس التعبير عن آرائهم بحرية",0]]},
  quiz:[["ماذا تعني «الشورى»؟",["مبدأ التشاور في اتخاذ القرار","نوع من الضرائب","رقصة تقليدية"],0],["كم عدد الإمارات التي كوّنت دولة الإمارات في 2 ديسمبر 1971؟",["سبع","ست","خمس"],1],["أيّ إمارة انضمت إلى الاتحاد في مطلع عام 1972؟",["الشارقة","الفجيرة","رأس الخيمة"],2],["ما المجلس الوطني الاتحادي؟",["منظمة رياضية","هيئة استشارية أُنشئت عام 1972","شركة خاصة"],1],["ما الفرق بين المساواة والإنصاف؟",["الإنصاف يراعي اختلاف الاحتياجات؛ والمساواة تعامل الجميع بالطريقة نفسها تمامًا","هما الشيء نفسه تمامًا","المساواة ظالمة دائمًا"],0],["ماذا يعني «التوافق»؟",["قرار يتخذه شخص واحد","تصويت يفوز به شخص واحد","اتفاق عام تتوصّل إليه مجموعة بعد النقاش"],2],["لماذا أسهم التشاور في صمود الاتحاد الإماراتي؟",["لأنه سمح لإمارة واحدة بالسيطرة على الإمارات الأخرى","لأن القرارات المتخذة بالتنازل المتبادل حظيت بشرعية وثقة أكبر","لأنه يعني عدم اتخاذ أي قرارات على الإطلاق"],1],["متى قد يكون اتخاذ قرار سريع من دون تشاور كامل مبرَّرًا؟",["في حالة طوارئ حقيقية قد يسبّب فيها التأخير ضررًا","كلما كان القائد مشغولًا","لا يكون مبرَّرًا تحت أي ظرف"],0]],
  exit:"في جملة واحدة، اشرح كيف أسهم التشاور (الشورى) في تحقيق الوحدة في دولة الإمارات.",
  copy:{facts:["الشورى (التشاور) مبدأ إسلامي ورد في القرآن الكريم، يقضي بأن تُتخذ القرارات بعد استطلاع آراء الآخرين.","كوّنت ست إمارات دولة الإمارات في 2 ديسمبر 1971، وانضمت رأس الخيمة عام 1972؛ وقد اعتمد الاتحاد على التفاوض والتنازل المتبادل والثقة.","يعكس المجلس الوطني الاتحادي (1972) وتقليد المجلس التشاور في الحكم الإماراتي؛ والإجراءات القائمة على العدل والتشاور تبني وحدة دائمة."]},
  next:"في الدرس القادم: نواصل الوحدة الأولى بدراسة رعاية الشيخ زايد للبيئة."
 },
 {
  id:"l5", lesson:5, title:"رعاية البيئة والحفاظ عليها", unit:"الوحدة الأولى: نهج زايد الأخلاقي", art:"nature",
  dna:"مراجعة: في جملة واحدة، اشرح مبدأ الشورى. والآن فكّر: تتميّز دولة الإمارات بأحد أقسى المناخات الصحراوية على وجه الأرض. ما المسؤولية الأخلاقية، إن وُجدت، التي تقع علينا في حماية البيئة من أجل أناس لم يولدوا بعد؟ اكتب جملة واحدة.",
  dnaQs:["في جملة واحدة، اشرح مبدأ الشورى (من الدرس السابق).","ما المسؤولية الأخلاقية التي تقع علينا في حماية البيئة من أجل أناس لم يولدوا بعد؟"],
  dnaHint:"في المراجعة: الشورى هي مبدأ التشاور — اتخاذ القرارات بعد استطلاع آراء الآخرين. أما في السؤال الثاني، فالإجابة القوية تستخدم فكرة المسؤولية بين الأجيال: فالأجيال القادمة لا تستطيع التحدث عن نفسها، لذا تتصرّف الأجيال الحاضرة بوصفها أمينة على البيئة. ويصف كثير من العلماء المسلمين الإنسان بأنه خليفة في الأرض (مستخلَف فيها وأمين عليها).",
  intentions:["أن أفهم التزام المغفور له الشيخ زايد بن سلطان آل نهيان، طيّب الله ثراه، برعاية البيئة، بما في ذلك التشجير والحفاظ على الحياة البرية.","أن أحلّل الأسس الأخلاقية لرعاية البيئة، بما في ذلك مفهوم الاستخلاف في الإسلام.","أن أقيّم التوتّرات الأخلاقية بين التنمية الاقتصادية وحماية البيئة، في الماضي والحاضر."],
  criteria:["أستطيع أن أشرح أمثلة محددة من جهود زايد البيئية شرحًا دقيقًا.","أستطيع أن أحلّل الأسس الأخلاقية والدينية لرعاية البيئة.","أستطيع أن أقيّم التوتّر بين التنمية والحفاظ على البيئة، وأقترح موقفًا مُعلَّلًا."],
  concept:{key:"الاستدامة", related:"الرعاية، المسؤولية، الأجيال القادمة", soi:"التعامل مع البيئة الطبيعية بوصفها أمانة يجب حمايتها للأجيال القادمة مسؤولية أخلاقية، لا مجرد خيار عملي.", context:"العولمة والاستدامة — استكشاف مسؤولية الإنسان تجاه العالم الطبيعي.", uae:"تبنّى الشيخ زايد تشجير الصحراء، ومحمية الحياة البرية في جزيرة صير بني ياس، وحماية أنواع مثل المها العربي، وممارسة الصيد بالصقور ممارسة مسؤولة؛ واستضافت دولة الإمارات مؤتمر COP28 عام 2023. يرتبط الدرس بمادتي الأحياء/أنظمة البيئة والمجتمعات والتربية الإسلامية (الاستخلاف)."},
  words:[["الرعاية / الأمانة (Stewardship)","العناية المسؤولة بشيء أُوكلت إلينا حمايته وإدارته، مثل البيئة."],["الخلافة / الاستخلاف (Khalifah)","في التعاليم الإسلامية، دور الإنسان بوصفه مستخلَفًا في الأرض وأمينًا عليها."],["التشجير (Afforestation)","زراعة الأشجار في منطقة لم تكن فيها غابات من قبل، مثل الأراضي الصحراوية."],["الحفاظ على البيئة (Conservation)","حماية البيئة الطبيعية والحياة البرية والموارد وصونها."],["العدالة بين الأجيال (Intergenerational justice)","مبدأ يقضي بأن على الأجيال الحاضرة واجبات في حماية مصالح الأجيال القادمة."],["التنوّع الحيوي (Biodiversity)","تنوّع الحياة النباتية والحيوانية في موطن معيّن أو في العالم بأسره."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار B — البحث والاستقصاء", steps:["اختر مبادرة بيئية واحدة مرتبطة بالشيخ زايد (مثل تشجير الصحراء، أو محمية الحياة البرية في جزيرة صير بني ياس، أو حماية المها العربي، أو دعمه للصيد المستدام بالصقور وحماية طيور الحبارى).","ابحث عنها مستخدمًا مصدرين موثوقين على الأقل.","دوّن: ما الذي تضمّنته المبادرة، والتحدي البيئي الذي عالجته، ونتيجتها.","حدّد القيمة الأخلاقية التي تعكسها (مثل الرعاية، أو العدالة بين الأجيال).","اربطها بجهد بيئي إماراتي حالي واحد (مثل زراعة أشجار القرم، أو مؤتمر COP28 عام 2023، أو مبادرة الإمارات الاستراتيجية للحياد المناخي 2050)."], prompts:["المبادرة التي اخترتها ومصدراي","ما الذي تضمّنته والتحدي الذي عالجته","نتيجتها","القيمة الأخلاقية التي تعكسها","جهد إماراتي حالي واحد يواصلها"], success:"تتميّز الإجابات القوية بالتحديد: فمثلًا، طُوّرت جزيرة صير بني ياس لتصبح محمية للحياة البرية رُبّيت فيها أنواع مثل المها العربي وحُميت، وحوّل التشجير مناطق من الصحراء من خلال زراعة الأشجار على نطاق واسع. تجنّب اختلاق الإحصاءات — ولا تستخدم الأرقام إلا إذا وردت في مصدر موثوق. وللوصول إلى أعلى مستوى، اشرح التعليل الأخلاقي (رؤية زايد بأن البيئة أمانة للأجيال القادمة، بما ينسجم مع مفهوم الاستخلاف)، واربط ربطًا واضحًا ودقيقًا بمبادرة حالية."},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"تخطّط مدينة ساحلية لإزالة مساحة من غابات القرم لبناء منتجع فاخر جديد. سيوفّر المشروع مئات الوظائف ويعزّز السياحة، لكن أشجار القرم تحمي الساحل وتخزّن الكربون وتوفّر موطنًا لأنواع كثيرة.", steps:["اكتب فقرة تقييمية حول السؤال: «هل ينبغي أن تُقدَّم التنمية الاقتصادية في أي وقت على حماية البيئة؟»","استخدم أربع كلمات على الأقل من بنك الكلمات (مثل الرعاية، العدالة بين الأجيال، الحفاظ على البيئة، التنوّع الحيوي) استخدامًا دقيقًا.","أشر إلى نهج زايد تجاه البيئة، وتوصّل إلى استنتاج مُعلَّل، مع النظر في إمكانية الوصول إلى حل وسط."], model:"تحقق التنمية الاقتصادية فوائد حقيقية، مثل الوظائف والسياحة، لكن لا ينبغي أن تُقدَّم تلقائيًا على حماية البيئة. فأشجار القرم تقدّم خدمات يصعب تعويضها: إذ تحمي الساحل، وتخزّن الكربون، وتحافظ على التنوّع الحيوي، لذا فإن إزالتها ستنقل الكلفة إلى أجيال قادمة لا صوت لها في القرار، وهذا يتعارض مع مبدأ العدالة بين الأجيال. ويشير نهج الشيخ زايد إلى طريق مختلف: فقد سعى إلى تنمية سريعة مع التعامل مع البيئة بوصفها أمانة، بما يعكس الفكرة الإسلامية عن الإنسان بوصفه مستخلَفًا في الأرض. ويمكن أن يتضمّن الحل الوسط بناء المنتجع على أرض أقل حساسية، أو تصميمه حول أشجار القرم ليكون معلمًا للسياحة البيئية. لذلك أستنتج أن التنمية مشروعة، لكن الرعاية تقتضي حماية النظم البيئية التي لا يمكن تعويضها أولًا، مع تكييف التنمية لتلائم الحدود البيئية.", rubric:[["1–2","تقييم ضعيف؛ استخدام محدود أو معدوم للمفردات الرئيسية."],["3–4","موقف أساسي بتعليل محدود؛ استخدام مصطلح أو مصطلحين رئيسيين."],["5–6","تقييم واضح يوازن بين الجانبين؛ استخدام 3 مصطلحات رئيسية بدقة؛ إشارة إلى نهج زايد."],["7–8","تقييم متقدّم ومتوازن؛ استخدام 4 مصطلحات رئيسية أو أكثر بدقة؛ دمج نهج زايد؛ اقتراح حل وسط واقعي ومُعلَّل."]], starters:["تحقق التنمية الاقتصادية فوائد مثل ___، لكن ___.","ستؤدي إزالة أشجار القرم إلى ___، وهذا يتعارض مع ___.","يشير نهج الشيخ زايد إلى ___.","يمكن أن يتضمّن الحل الوسط ___، لذلك أستنتج أن ___."]},
  task3:{title:"مهمة المشروع", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"مقترح عمل لرعاية البيئة", steps:["في مجموعات من 3–4 طلاب، حدّدوا قضية بيئية واحدة تؤثر في مدرستكم أو مجتمعكم المحلي في دولة الإمارات (مثل البلاستيك أحادي الاستخدام، أو استهلاك المياه، أو استخدام الطاقة، أو هدر الطعام).","اجمعوا أدلة بسيطة على القضية (مثل تدقيق قصير أو ملاحظة على مدى أسبوع)، بموافقة المعلم.","صمّموا مقترح عمل واقعيًا مستوحى من رعاية زايد للبيئة، بأهداف قابلة للقياس.","حدّدوا عقبة أخلاقية أو عملية واحدة (مثل الكلفة، أو الراحة، أو تغيير السلوك) وكيف ستتغلّبون عليها.","قدّموا مقترحكم في عرض مدته 4 دقائق أمام «لجنة» (الصف)، مستخدمين مفردات بنك الكلمات."], rubric:[["1–2","القضية غامضة؛ لا أدلة ولا أهداف قابلة للقياس."],["3–4","القضية محدّدة مع أدلة محدودة؛ المقترح عام."],["5–6","قضية واضحة مدعومة بالأدلة؛ مقترح واقعي بأهداف قابلة للقياس؛ معالجة العقبة."],["7–8","مقترح مدعوم بالأدلة جيدًا، وعملي، وقابل للقياس؛ تحليل العقبة بعمق؛ ربط قوي وصريح برعاية زايد للبيئة والعدالة بين الأجيال."]]},
  game:{type:"sort", title:"رعاية أم استنزاف؟", prompt:"صنّف كل تصرّف: هل يعكس رعاية البيئة، أم استنزافها؟", bins:["رعاية","استنزاف"], items:[["زراعة الأشجار لتخضير مناطق من الصحراء",0],["تربية المها العربي المهدّد بالانقراض في محمية",0],["الإفراط في صيد الحيوانات البرية حتى يصبح النوع مهدّدًا بالانقراض",1],["تنظيم الصيد بالصقور لحماية أعداد الطيور البرية",0],["إزالة أشجار القرم من دون مراعاة النظام البيئي",1],["إلقاء النفايات في البحر توفيرًا للمال",1],["زراعة أشجار القرم لحماية الساحل",0],["هدر المياه في بلد صحراوي شحيح الموارد المائية",1]]},
  quiz:[["ماذا يعني «الاستخلاف» في التعاليم الإسلامية حول البيئة؟",["الإنسان مستخلَف في الأرض وأمين عليها","نوع من الأشجار","حيوان صحراوي"],0],["أيّ جزيرة طوّرها الشيخ زايد لتكون محمية للحياة البرية؟",["جزيرة السعديات","جزيرة صير بني ياس","جزيرة ياس"],1],["ما «التشجير»؟",["قطع الغابات","زراعة الأشجار في منطقة لم تكن فيها غابات من قبل","نوع من الزراعة"],1],["أيّ الأنواع المهدّدة بالانقراض ترتبط بجهود الحفاظ عليها في صير بني ياس؟",["المها العربي","الدب القطبي","الباندا العملاقة"],0],["ماذا تعني «العدالة بين الأجيال»؟",["العدالة لكبار السن فقط","القوانين المتعلقة بالمدارس","واجب الأجيال الحاضرة في حماية مصالح الأجيال القادمة"],2],["لماذا تُعدّ أشجار القرم مهمة بيئيًا؟",["لأنها تحمي السواحل، وتخزّن الكربون، وتوفّر مواطن للكائنات","لأنه لا قيمة بيئية لها","لأنها للزينة فقط"],0],["أيّ مؤتمر مناخي عالمي استضافته دولة الإمارات عام 2023؟",["COP21","COP26","COP28"],2],["ماذا يشير إليه نهج زايد بشأن التنمية والبيئة؟",["يجب أن تتوقف التنمية دائمًا لحماية الطبيعة","يمكن أن تمضي التنمية قُدمًا مع التعامل مع البيئة بوصفها أمانة","البيئة لا تهم في الصحراء"],1]],
  exit:"في جملة واحدة، اشرح لماذا تُعدّ رعاية البيئة مسؤولية أخلاقية، لا مجرد خيار عملي.",
  copy:{facts:["تبنّى الشيخ زايد رعاية البيئة من خلال تشجير الصحراء، ومحمية الحياة البرية في جزيرة صير بني ياس، وحماية المها العربي، والصيد المسؤول بالصقور.","يصف مفهوم الاستخلاف في الإسلام الإنسان بأنه أمين على الأرض، وتعني العدالة بين الأجيال أن علينا حماية البيئة للأجيال القادمة.","يبيّن نهج زايد أنه يمكن الموازنة بين التنمية والحفاظ على البيئة؛ وتواصل دولة الإمارات ذلك من خلال زراعة أشجار القرم واستضافة مؤتمر COP28 عام 2023."]},
  next:"في الدرس القادم: نختتم الوحدة الأولى باستكشاف كيف نعيش إرث زايد اليوم."
 },
 {
  id:"l6", lesson:6, title:"إرث زايد في حياتنا اليوم", unit:"الوحدة الأولى: نهج زايد الأخلاقي", art:"future",
  dna:"مراجعة مفردات الوحدة الأولى! عرّف كل مصطلح بأسلوبك الخاص: الشرعية، التعايش، الصدقة، الشورى، الرعاية. هذا هو الدرس الأخير في الوحدة الأولى — أيّ قيم المغفور له الشيخ زايد بن سلطان آل نهيان، طيّب الله ثراه، ترى أن العالم في أمسّ الحاجة إليها اليوم؟",
  dnaQs:["الشرعية والتعايش — ماذا يعني كل منهما؟","الصدقة والشورى — ماذا يعني كل منهما؟","الرعاية — ماذا تعني؟ وأيّ قيم زايد يحتاج إليها العالم أكثر اليوم؟"],
  dnaHint:"الشرعية: القبول بأن سلطة القائد سلطة مستحقّة. التعايش: العيش معًا بسلام في ظل الاحترام المتبادل رغم الاختلافات. الصدقة: العطاء الخيري التطوّعي في الإسلام. الشورى: مبدأ التشاور في اتخاذ القرار. الرعاية: العناية المسؤولة بشيء أُوكل إلينا، مثل البيئة. أما السؤال الأخير، فأي قيمة يمكن أن تنال الدرجة إذا علّلت اختيارك بمثال معاصر.",
  intentions:["أن أُجمِل القيم الأساسية لنهج زايد الأخلاقي التي درستها في الوحدة الأولى في رؤية متكاملة.","أن أحلّل كيف يمكن لهذه القيم أن توجّه الخيارات الشخصية والمسؤولية المدنية للشباب في دولة الإمارات اليوم.","أن أقيّم معنى أن نرث إرثًا، وأن أصمّم التزامًا شخصيًا بعيش هذه القيم."],
  criteria:["أستطيع أن أُجمِل قيم زايد الأساسية بأمثلة دقيقة من مختلف دروس الوحدة.","أستطيع أن أحلّل كيف تنطبق هذه القيم على خيارات حقيقية يواجهها الشباب اليوم.","أستطيع أن أقيّم معنى الإرث وأعلّل التزامًا شخصيًا."],
  concept:{key:"الهوية", related:"الإرث، المواطنة، المسؤولية", soi:"يدوم الإرث الأخلاقي عندما يفسّر كل جيل قيمه ويترجمها إلى أفعال في ظروف جديدة.", context:"الهويات والعلاقات — استكشاف كيف تُسهم القيم الموروثة في تشكيل الهوية الشخصية والوطنية.", uae:"يجمع هذا الدرس محاور الوحدة: القيادة القائمة على القيم (الدرس 1)، والتسامح (الدرس 2)، والكرم ويوم زايد للعمل الإنساني (الدرس 3)، والشورى والوحدة (الدرس 4)، ورعاية البيئة (الدرس 5)؛ ويرتبط بـ«عام زايد» في دولة الإمارات (2018)، وبرنامج الإبداع والنشاط والخدمة (CAS)، والمقال الموسّع في برنامج الدبلوم."},
  words:[["الإرث (Legacy)","القيم والإنجازات والأثر التي يتركها الشخص للأجيال القادمة."],["المسؤولية المدنية (Civic responsibility)","واجبات المواطن أو المقيم في الإسهام الإيجابي في مجتمعه."],["التوليف / الإجمال (Synthesis)","الجمع بين أفكار مختلفة لتكوين كلٍّ متماسك أو فهم جديد."],["القدوة الأخلاقية (Moral exemplar)","شخص يُعدّ سلوكه نموذجًا للقيم الأخلاقية يحتذي به الآخرون."],["المواطنة الفاعلة (Active citizenship)","المشاركة في حياة المجتمع من خلال الخدمة والانخراط والعمل المسؤول."],["الالتزام (Commitment)","التفاني في قيمة أو قضية أو مسار عمل، أو التعهّد به."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار A — المعرفة والفهم", steps:["اختر مبادرة أو منظمة أو برنامجًا إماراتيًا حاليًا واحدًا ترى أنه يواصل إرث زايد (مثل منصة للتطوّع، أو حملة إنسانية، أو برنامج بيئي، أو مبادرة للتسامح).","ابحث عنه مستخدمًا مصدرين موثوقين على الأقل.","دوّن: ما الذي يقوم به، ومن يشارك فيه، وأيّ قيم زايد يعكس (من الدروس 1–5).","حدّد طريقة واحدة يمكن للشباب في مثل سنّك المشاركة بها فيه، أو في مبادرة مشابهة.","قيّم: إلى أي مدى يعكس قيم زايد بأمانة، وفي أي جانب يمكن أن يذهب أبعد؟"], prompts:["المبادرة التي اخترتها ومصدراي","ما الذي تقوم به ومن يشارك فيها","أيّ قيم زايد تعكس","طريقة واحدة يمكن للشباب المشاركة بها","إلى أي مدى تعكس قيم زايد بأمانة، وأين يمكن أن تذهب أبعد"], success:"تربط الإجابات القوية ربطًا دقيقًا بقيمة واحدة على الأقل مما دُرس في الوحدة (فمثلًا، يعكس برنامج التطوّع الكرم والمواطنة الفاعلة؛ ويعكس مشروع زراعة أشجار القرم رعاية البيئة). وينبغي أن تكون الإجابات دقيقة ويمكن التحقق منها، لا مجرد ثناء عام. وللوصول إلى أعلى مستوى، قدّم تقييمًا عميقًا — مثلًا، هل تصل المبادرة إلى جميع فئات المجتمع، أو هل المشاركة فيها حقيقية لا رمزية — وحدّد طريقة واقعية لإسهام الطلاب، مثل برنامج الإبداع والنشاط والخدمة (CAS)."},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"تأمّل في الوحدة الأولى: الدرس 1 (القيادة القائمة على القيم)، والدرس 2 (التسامح والتعايش)، والدرس 3 (الكرم والعمل الإنساني)، والدرس 4 (العدل والشورى والوحدة)، والدرس 5 (رعاية البيئة).", steps:["اكتب فقرة مقالية توليفية تجيب فيها عن السؤال: «هل الإرث شيء نرثه، أم شيء يجب أن نختار مواصلته؟»","اربط بين ثلاثة دروس على الأقل من الوحدة، واستخدم خمسة مصطلحات رئيسية على الأقل من بنوك الكلمات في الوحدة استخدامًا دقيقًا.","اختم بتأمّل فيما يمكن أن يعنيه عيش إرث زايد في حياتك خلال العامين القادمين."], model:"الإرث شيء نرثه ونختاره في آن واحد: فنحن نرث قيمه، لكنه لا يبقى إلا إذا قرّر كل جيل بفاعلية أن يواصله. لقد ترك الشيخ زايد إرثًا أخلاقيًا واضحًا — قيادة قائمة على القيم ومتجذّرة في التواضع، ورؤية للتعايش بين أناس من جنسيات كثيرة، وكرمًا تجلّى في العمل الإنساني، ووحدة بُنيت على الشورى والتنازل المتبادل، ورعاية للبيئة بوصفها أمانة للأجيال القادمة. غير أن هذه القيم لا تُصان تلقائيًا بالنُّصُب التذكارية أو المناسبات السنوية؛ بل تدوم فقط حين يترجمها الناس إلى أفعال في ظروف جديدة، مثل استخدام المنصات الرقمية لتنسيق العمل التطوّعي، أو تطبيق مبدأ الرعاية على تحدّي تغيّر المناخ. وبالنسبة إليّ، قد يعني عيش هذا الإرث خلال العامين القادمين الالتزام بالمواطنة الفاعلة من خلال برنامج الإبداع والنشاط والخدمة، والتشاور مع الآخرين بإنصاف في العمل الجماعي، واتخاذ خيارات مسؤولة بيئيًا، لأن الإرث الذي يُعجَب به الناس ولا يمارسونه سرعان ما يصبح مجرد تاريخ.", rubric:[["1–2","توليف محدود؛ روابط قليلة بين الدروس؛ استخدام ضئيل للمفردات الرئيسية."],["3–4","بعض الروابط، ومعظمها وصفي؛ استخدام 2–3 مصطلحات رئيسية."],["5–6","توليف واضح عبر ثلاثة دروس؛ استخدام 4 مصطلحات رئيسية بدقة؛ تضمين تأمّل شخصي."],["7–8","توليف متقدّم عبر الوحدة؛ استخدام 5 مصطلحات رئيسية أو أكثر بدقة؛ حجة دقيقة حول الإرث؛ تأمّل شخصي محدد ومقنع."]], starters:["الإرث شيء نرثه ونختاره في آن واحد، لأن ___.","يتضمّن الإرث الأخلاقي للشيخ زايد ___ و___ و___.","لا تدوم هذه القيم إلا حين ___.","بالنسبة إليّ، قد يعني عيش هذا الإرث خلال العامين القادمين ___، لأن ___."]},
  task3:{title:"مهمة المشروع (عرض الوحدة)", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"خطة الإرث في العمل", steps:["بشكل فردي أو في أزواج، اختر قيمة واحدة من قيم زايد التي درستها في هذه الوحدة وتريد أن تحوّلها إلى عمل.","صمّم خطة واقعية بعنوان «الإرث في العمل» للفصل الدراسي القادم (يمكن أن تصبح مشروعًا ضمن برنامج الإبداع والنشاط والخدمة)، بأهداف واضحة وقابلة للقياس.","حدّد الفئة المجتمعية التي ستخدمها الخطة، والموارد اللازمة، واعتبارًا أخلاقيًا واحدًا (مثل احترام كرامة من تساعدهم، أو استشارة الأطراف المعنية).","اعرض خطتك على الصف في «عرض الإرث» مدته 3 دقائق، تشرح فيه كيف ترتبط بنهج زايد الأخلاقي.","اجمعوا جميع الخطط على مستوى الصف في «جدار الإرث» المشترك، واتفقوا على خطة واحدة تنفّذونها معًا بوصفكم صفًّا دراسيًا."], rubric:[["1–2","الخطة غامضة؛ ارتباط ضعيف بقيم زايد."],["3–4","خطة أساسية بأهداف عامة؛ ارتباط محدود بالوحدة."],["5–6","خطة واضحة وواقعية بأهداف قابلة للقياس؛ معالجة الاعتبار الأخلاقي؛ ربط صريح بقيمة من قيم الوحدة."],["7–8","خطة عملية وطموحة ومُعلَّلة جيدًا؛ تحليل عميق للاعتبارات الأخلاقية؛ روابط عميقة عبر نهج زايد الأخلاقي."]]},
  game:{type:"sort", title:"أيّ قيمة من إرث زايد؟", prompt:"صنّف كل تصرّف معاصر بحسب القيمة التي يعكسها على أفضل وجه من نهج زايد الأخلاقي.", bins:["التسامح والتعايش","الكرم والعطاء","الشورى والوحدة","رعاية البيئة"], items:[["تنظيم إفطار مجتمعي يجمع أتباع أديان مختلفة",0],["التطوّع في حملة لتوزيع الطعام خلال شهر رمضان",1],["استشارة جميع أعضاء المجموعة قبل اتخاذ القرار",2],["المشاركة في يوم لزراعة أشجار القرم",3],["الترحيب بطالب جديد قادم من بلد مختلف",0],["التبرّع لنداء إغاثة موثوق في يوم زايد للعمل الإنساني",1],["الحدّ من البلاستيك أحادي الاستخدام في مقصف المدرسة",3],["مساعدة مجموعتين متنافستين على التنازل المتبادل للوصول إلى اتفاق",2]]},
  quiz:[["ما «الإرث»؟",["القيم والأثر اللذان يتركهما الشخص للأجيال القادمة","نوع من المباني","دائرة حكومية"],0],["أيّ قيمة تنعكس في تقليد المجلس لدى الشيخ زايد؟",["العزلة عن الناس","القرب من الناس والتشاور معهم","التنافس بين المواطنين"],1],["أيّ المبادرات الآتية تعكس رعاية زايد للبيئة؟",["محمية الحياة البرية في جزيرة صير بني ياس","المجلس الوطني الاتحادي","وزارة التسامح"],0],["ماذا تعني «المواطنة الفاعلة»؟",["تجنّب المشاركة في حياة المجتمع","التصويت في الانتخابات فقط","المشاركة في حياة المجتمع من خلال الخدمة والعمل المسؤول"],2],["يرتبط يوم زايد للعمل الإنساني بأيّ قيمة؟",["الكرم والعطاء الإنساني","القوة العسكرية","المنافسة الاقتصادية"],0],["احتفى «عام زايد» (2018) بـ…",["تأسيس دولة الإمارات","مئوية ميلاد الشيخ زايد","اكتشاف النفط"],1],["لماذا قد يكون الإرث شيئًا «نختاره» لا مجرد شيء «نرثه»؟",["لأن النُّصُب التذكارية تحفظ القيم تلقائيًا","لأن الإرث يتعلّق بالتاريخ فقط","لأن القيم لا تدوم إلا حين يعمل بها كل جيل"],2],["أيّ مما يأتي هو أقوى مثال على عيش إرث زايد بوصفك طالبًا؟",["حفظ معلومات عنه من دون تغيير السلوك","الالتزام بمشروع ضمن برنامج الإبداع والنشاط والخدمة يخدم المجتمع ويحترم الآخرين","الحديث عن القيم من دون العمل بها"],1]],
  exit:"اكتب عملًا محددًا واحدًا ستقوم به هذا الفصل الدراسي لتعيش قيمة من قيم زايد، واشرح القيمة التي يعكسها.",
  copy:{facts:["يجمع نهج زايد الأخلاقي بين القيادة القائمة على القيم، والتسامح والتعايش، والكرم، والعدل والشورى، ورعاية البيئة.","لا يدوم الإرث إلا حين يفسّر كل جيل قيمه بفاعلية ويحوّلها إلى أفعال في ظروف جديدة.","يستطيع الشباب أن يعيشوا إرث زايد من خلال المواطنة الفاعلة، والتطوّع، والتشاور المنصف، والخيارات المسؤولة بيئيًا — بما في ذلك من خلال برنامج الإبداع والنشاط والخدمة (CAS)."]},
  next:"اكتملت الوحدة الأولى: نهج زايد الأخلاقي! وفي الدرس القادم، نبدأ الوحدة الثانية."
 }
];
